INSERT INTO registry_stack_presets (id, release_id, preset_type, preset_kind, parent_pattern_id, name, app_type_ids, details_json, sort_order) VALUES ('P1', 1, 'architecture_pattern', 'pattern_definition', NULL, '統合型Webアプリ', NULL, '{"description":"フロント・バックエンド・管理画面を一つのフレームワークで構築","complexityLevel":2,"suitableConditions":["小中規模","開発者少数","単一チームで完結","納期優先"],"unsuitableConditions":["大規模同時アクセス","フロント/バックエンドを別チームで運用したい"],"candidates":["Django","Laravel","Ruby on Rails","ASP.NET Core","Spring Boot＋テンプレート","Next.js単体構成"]}', 0);
INSERT INTO registry_stack_presets (id, release_id, preset_type, preset_kind, parent_pattern_id, name, app_type_ids, details_json, sort_order) VALUES ('P2', 1, 'architecture_pattern', 'pattern_definition', NULL, 'フロント・API分離型', NULL, '{"description":"画面とAPIを分離し、モバイル共有や長期拡張に備える","complexityLevel":3,"suitableConditions":["モバイルアプリとAPI共有","外部公開SaaS","長期拡張前提"],"unsuitableConditions":["MVP・小規模・開発速度最優先"],"candidates":["React","Vue","Angular","Next.js","Nuxt","NestJS","FastAPI","ASP.NET Core","Go"]}', 1);
INSERT INTO registry_stack_presets (id, release_id, preset_type, preset_kind, parent_pattern_id, name, app_type_ids, details_json, sort_order) VALUES ('P3', 1, 'architecture_pattern', 'pattern_definition', NULL, 'BaaS中心型', NULL, '{"description":"認証・DB・ストレージ・リアルタイムをBaaSで構築","complexityLevel":1,"suitableConditions":["MVP","少人数開発","AIコーディング中心","開発速度最優先"],"unsuitableConditions":["複雑なSQL集計","オンプレミス必須","厳密なトランザクション制御"],"candidates":["Supabase","Firebase","Appwrite","PocketBase","AWS Amplify"]}', 2);
INSERT INTO registry_stack_presets (id, release_id, preset_type, preset_kind, parent_pattern_id, name, app_type_ids, details_json, sort_order) VALUES ('P4', 1, 'architecture_pattern', 'pattern_definition', NULL, 'Microsoft統合型', NULL, '{"description":"Microsoft 365 / Entra ID / Azureを前提とした構成","complexityLevel":3,"suitableConditions":["Microsoft 365利用","Entra ID必須","Windows/Azure統一"],"unsuitableConditions":["Microsoft環境がない","脱Microsoftを志向"],"candidates":["ASP.NET Core","Blazor","Azure SQL","Entra ID","Azure Functions","Power Platform"]}', 3);
INSERT INTO registry_stack_presets (id, release_id, preset_type, preset_kind, parent_pattern_id, name, app_type_ids, details_json, sort_order) VALUES ('P5', 1, 'architecture_pattern', 'pattern_definition', NULL, 'Python業務・AI型', NULL, '{"description":"AI/RAG、データ処理、自動化を中心とした構成","complexityLevel":2,"suitableConditions":["AI/RAG","PDF・Excel処理","データ分析・自動化"],"unsuitableConditions":["リッチなSPA UIが必須","リアルタイム性が極めて高い"],"candidates":["Python","Django","FastAPI","Flask","Streamlit","Gradio","Celery","Pandas"]}', 4);
INSERT INTO registry_stack_presets (id, release_id, preset_type, preset_kind, parent_pattern_id, name, app_type_ids, details_json, sort_order) VALUES ('P6', 1, 'architecture_pattern', 'pattern_definition', NULL, 'SaaS連携・自動化型', NULL, '{"description":"SaaS間のデータ同期・定期処理・通知の自動化が主目的","complexityLevel":1,"suitableConditions":["SaaS間データ同期","定期処理","通知の自動化が主目的"],"unsuitableConditions":["独自UIを持つ業務システム本体が必要"],"candidates":["n8n","Make","Zapier","Power Automate","Python","Node.js","Cloud Functions"]}', 5);
INSERT INTO registry_stack_presets (id, release_id, preset_type, preset_kind, parent_pattern_id, name, app_type_ids, details_json, sort_order) VALUES ('P7', 1, 'architecture_pattern', 'pattern_definition', NULL, 'モバイル中心型', NULL, '{"description":"現場入力・オフライン利用・端末機能が中核","complexityLevel":3,"suitableConditions":["現場入力","オフライン利用","位置情報・カメラ等端末機能が中核"],"unsuitableConditions":["PC管理画面が主用途"],"candidates":["Swift","Kotlin","Flutter","React Native","Expo","Capacitor"]}', 6);
