INSERT INTO registry_stack_presets (id, release_id, preset_type, preset_kind, parent_pattern_id, name, app_type_ids, details_json, sort_order) VALUES ('WEB-01', 1, 'tech_pattern', NULL, NULL, '最速Web MVP', NULL, '{"shortSummary":"Supabaseで認証・DB・ストレージを一括管理し、Reactの操作性の高い画面と組み合わせた、最速で公開できるMVP構成です。","primaryUse":"新規サービスのMVP開発","architectureType":"オールインワン構成","primaryLanguage":"TypeScript中心","whatYouCanBuild":"React＋ViteのSPAをSupabaseと直結し、会員登録・ログイン、データの保存、ファイルのアップロードまでを最短距離で実装したWebサービスを構築できます。バックエンドサーバーを自前で用意せず、Vercelへそのまま公開できます。","whyRecommended":["React＋Viteにより、動作が軽快なSPA画面を素早く構築できます。Supabaseの自動生成APIから直接データを操作できるため、専用のバックエンド開発を省略できます。","認証・DB・ストレージ・ホスティングをSupabaseとVercelに集約しているため、複数サービスの契約や連携設定に時間を取られず、アイデアの検証を素早く行えます。"],"strengths":["セットアップから公開までが速い","認証・DB・ストレージを一元管理できる","サーバー運用の手間がほぼない","小さく始めて段階的に機能追加できる","Vercelで自動デプロイできる"],"suitableCases":["新規事業のアイデアを素早く検証したい","小規模な会員制サービスを立ち上げたい","開発リソースが少ないチームで開発したい","将来的に機能を追加しながら育てたい"],"unsuitableCases":["複雑な業務ロジックや承認フローが必要","大量データの高度な集計処理が必要","既存の社内システムと密に連携する必要がある"],"expectedFeatures":["ログイン・ユーザー管理","データの登録・一覧・編集","ファイルアップロード","リアルタイム更新","検索・絞り込み"]}', 0);
INSERT INTO registry_stack_presets (id, release_id, preset_type, preset_kind, parent_pattern_id, name, app_type_ids, details_json, sort_order) VALUES ('WEB-02', 1, 'tech_pattern', NULL, NULL, 'Vue最速MVP', NULL, '{"shortSummary":"VueとSupabaseを組み合わせ、少人数のチームでも最短距離で新規サービスを立ち上げられるMVP構成です。","primaryUse":"新規サービスのMVP開発","architectureType":"オールインワン構成","primaryLanguage":"TypeScript中心","whatYouCanBuild":"Vue＋ViteのSPAとSupabaseを組み合わせ、認証・データ保存・ファイル管理を備えた小規模なWebサービスを構築できます。VercelにそのままデプロイできるためMVPの公開までが速いです。","whyRecommended":["Vueの直感的な記法とSupabaseのマネージド機能を組み合わせることで、少人数のチームでも短期間でサービスを形にできます。認証やDB操作を自前で作り込む必要がありません。"],"strengths":["学習コストの低いVueで開発できる","認証・DBの構築が不要","Vercelで公開まで速い","小規模チームで完結できる"],"suitableCases":["Vue採用チームで新規サービスを検証したい","小規模な社内ツールを短期間で作りたい"],"unsuitableCases":["複雑な業務ロジックが必要","SEOを最優先するコンテンツサイトを作りたい","大規模なチーム開発を想定している"],"expectedFeatures":["ログイン・ユーザー管理","データの登録・一覧・編集","ファイルアップロード","検索・絞り込み"]}', 1);
INSERT INTO registry_stack_presets (id, release_id, preset_type, preset_kind, parent_pattern_id, name, app_type_ids, details_json, sort_order) VALUES ('WEB-03', 1, 'tech_pattern', NULL, NULL, '標準Next.js SaaS', NULL, '{"shortSummary":"Next.js一本でフロント・API・認証・DBを完結させる、標準的な小〜中規模SaaSの構成です。","primaryUse":"業務SaaSの構築","architectureType":"フロントエンド統合型","primaryLanguage":"TypeScript中心","whatYouCanBuild":"Next.js一本でフロント画面・API処理（Server Actions）・認証・DBまでをまかない、月額課金や予約管理など標準的な業務SaaSを構築できます。","whyRecommended":["フロントとサーバー処理を同じNext.jsプロジェクトに統合できるため、開発チームを分けずに一つのコードベースでSaaSを完結できます。SEOにも対応しやすい構成です。"],"strengths":["フロントとAPIを一つのプロジェクトで管理できる","SEO対応がしやすい","Vercelで運用しやすい","型安全なデータ操作ができる"],"suitableCases":["月額課金制のSaaSを立ち上げたい","予約・受付管理サービスを作りたい","SEOも意識した会員制サービスを作りたい"],"unsuitableCases":["複雑な業務ロジックを持つ基幹システム","モバイルアプリとの同時展開が前提","大規模なチームでの分業開発"],"expectedFeatures":["ログイン・ユーザー管理","課金・プラン管理","データの登録・一覧・編集","ファイルアップロード","ダッシュボード"]}', 2);
INSERT INTO registry_stack_presets (id, release_id, preset_type, preset_kind, parent_pattern_id, name, app_type_ids, details_json, sort_order) VALUES ('WEB-04', 1, 'tech_pattern', NULL, NULL, '本格Next.js SaaS', NULL, '{"shortSummary":"Next.jsを軸に、Clerk・S3・Sentryなど専用サービスを組み合わせた本格的なSaaSの構成です。","primaryUse":"本格的なB2B/B2C SaaSの構築","architectureType":"フロントエンド統合型","primaryLanguage":"TypeScript中心","whatYouCanBuild":"Next.jsを軸に、PrismaによるDB操作、Clerkによる組織・招待管理、Amazon S3でのファイル保存、Sentryでの障害監視まで揃えた、複数プランやチーム機能を持つ本格的なSaaSを構築できます。","whyRecommended":["認証・DB操作・監視をそれぞれ専用サービスに任せることで、利用者数やデータ量が増えても機能追加・運用がしやすい構成になっています。","組織・招待・権限管理をClerkに任せられるため、BtoB SaaS特有のチーム機能をゼロから作り込む必要がありません。"],"strengths":["組織・招待管理を作り込まずに実装できる","障害監視を最初から組み込める","データ量が増えても拡張しやすい","型安全なDB操作ができる"],"suitableCases":["複数プランを持つ本格的なSaaSを作りたい","チーム・組織単位で使われるBtoBサービス","長期運用と障害監視を重視したい"],"unsuitableCases":["数週間で終わる短期プロトタイプ","個人利用中心の小規模ツール","既存SaaSへの外部委託の方が合理的な機能"],"expectedFeatures":["ログイン・組織管理","プラン・課金管理","ファイルアップロード","操作履歴・監視","ダッシュボード","外部API連携"]}', 3);
INSERT INTO registry_stack_presets (id, release_id, preset_type, preset_kind, parent_pattern_id, name, app_type_ids, details_json, sort_order) VALUES ('WEB-05', 1, 'tech_pattern', NULL, NULL, 'Google統一Webアプリ', NULL, '{"shortSummary":"認証・DB・ホスティングをすべてGoogle/Firebaseに統一した、リアルタイム性の高いWebアプリ構成です。","primaryUse":"Google連携Webアプリの構築","architectureType":"Google Cloud統一構成","primaryLanguage":"TypeScript中心","whatYouCanBuild":"Next.jsのフロントに、Firebase AuthenticationによるGoogleログイン、Firestoreでのリアルタイムデータ管理、Cloud Functionsでの処理を組み合わせたWebアプリを構築できます。","whyRecommended":["認証からデータ、ホスティングまでをGoogle/Firebaseに統一することで、サービス間の連携設定が少なく、Googleアカウントを前提とした業務ツールと相性がよい構成です。"],"strengths":["Googleログインとの親和性が高い","リアルタイム同期が得意","サーバー管理がほぼ不要","Google Workspaceと連携しやすい"],"suitableCases":["Googleアカウント連携が前提のサービス","リアルタイム性が求められる小規模SaaS"],"unsuitableCases":["複雑な関係データを扱う基幹システム","Google以外のクラウドに統一したい","複雑な集計・レポート機能が中心"],"expectedFeatures":["Googleログイン","リアルタイムデータ同期","通知・メール送信","データの登録・一覧・編集"]}', 4);
INSERT INTO registry_stack_presets (id, release_id, preset_type, preset_kind, parent_pattern_id, name, app_type_ids, details_json, sort_order) VALUES ('WEB-06', 1, 'tech_pattern', NULL, NULL, 'オフライン対応PWA', NULL, '{"shortSummary":"PWA化により、電波の弱い環境でも使えるオフライン対応のアプリのようなWeb体験を提供する構成です。","primaryUse":"現場向けオフライン対応アプリ","architectureType":"PWA構成","primaryLanguage":"TypeScript中心","whatYouCanBuild":"PWA化したWeb画面とFirestoreを組み合わせ、電波の弱い環境でも記録や閲覧を続けられるオフライン対応のアプリのようなWebサービスを構築できます。","whyRecommended":["アプリストアの審査を経ずに、ホーム画面への追加やオフライン動作といったアプリに近い体験を提供できるため、現場作業などすぐに配布したい場面に向きます。"],"strengths":["アプリストア審査が不要","オフラインでも動作する","URL一つで配布できる","Web技術の知識で開発できる"],"suitableCases":["現場作業員向けの記録アプリ","電波の弱い環境で使う業務ツール","すぐに配布・更新したいツール"],"unsuitableCases":["高度なネイティブ機能（Bluetooth等）が中心","ストア経由での正式配布が必須","複雑な業務システム"],"expectedFeatures":["オフライン記録・同期","ホーム画面への追加","プッシュ通知","データの登録・一覧"]}', 5);
INSERT INTO registry_stack_presets (id, release_id, preset_type, preset_kind, parent_pattern_id, name, app_type_ids, details_json, sort_order) VALUES ('WEB-07', 1, 'tech_pattern', NULL, NULL, 'Nuxt SaaS', NULL, '{"shortSummary":"NuxtのSSR機能とSupabaseを組み合わせた、SEOを意識したVueベースのSaaS構成です。","primaryUse":"SEO重視のVue SaaS構築","architectureType":"フロントエンド統合型","primaryLanguage":"TypeScript中心","whatYouCanBuild":"NuxtのSSR機能とSupabaseを組み合わせ、SEOを意識した会員制サービスやコンテンツ配信を伴うSaaSを構築できます。","whyRecommended":["VueチームがSEOを重視するサービスを作る場合に、SSR対応とSupabaseの手軽さを両立できる構成です。"],"strengths":["SEOに強いSSR構成","Supabaseで開発が速い","Vueの知識をそのまま活かせる"],"suitableCases":["SEOを重視するVueチームのSaaS","コンテンツ配信を伴う会員制サービス"],"unsuitableCases":["SEOを必要としない社内ツール","複雑な業務ロジックが中心のシステム"],"expectedFeatures":["ログイン・ユーザー管理","コンテンツ配信","検索・絞り込み","ファイルアップロード"]}', 6);
INSERT INTO registry_stack_presets (id, release_id, preset_type, preset_kind, parent_pattern_id, name, app_type_ids, details_json, sort_order) VALUES ('WEB-08', 1, 'tech_pattern', NULL, NULL, 'SvelteKit軽量SaaS', NULL, '{"shortSummary":"SvelteKitとSupabaseを組み合わせ、少ないコード量で高速に動作する軽量SaaS構成です。","primaryUse":"軽量SaaSの構築","architectureType":"フロントエンド統合型","primaryLanguage":"TypeScript中心","whatYouCanBuild":"SvelteKitとSupabaseを組み合わせ、少ないコード量で高速に動作する小規模なSaaSを構築できます。","whyRecommended":["SvelteKitのコンパイル時最適化により、軽量で表示速度を重視したサービスを、シンプルな構成で実現できます。"],"strengths":["コード量が少なく済む","表示速度が速い","Supabaseで開発が速い"],"suitableCases":["表示速度を重視する小規模SaaS","コード量を抑えたいチームのサービス開発"],"unsuitableCases":["大規模なチームでの分業開発","エコシステムの豊富さが必要な複雑なシステム"],"expectedFeatures":["ログイン・ユーザー管理","データの登録・一覧・編集","ファイルアップロード"]}', 7);
INSERT INTO registry_stack_presets (id, release_id, preset_type, preset_kind, parent_pattern_id, name, app_type_ids, details_json, sort_order) VALUES ('WEB-09', 1, 'tech_pattern', NULL, NULL, 'Astroコンテンツサイト', NULL, '{"shortSummary":"静的生成中心の高速な表示と、必要な箇所だけ動的にするコンテンツサイトの構成です。","primaryUse":"コンテンツサイトの構築","architectureType":"静的サイト構成","primaryLanguage":"TypeScript中心","whatYouCanBuild":"Astroの静的生成とアイランド構成により、コーポレートサイトやオウンドメディア、製品ドキュメントなど、表示速度とSEOを重視したコンテンツサイトを構築できます。","whyRecommended":["ページの大部分を静的HTMLとして配信し、必要な部分だけJavaScriptを読み込むため、管理画面のような動的なアプリより高速な表示とSEO評価が期待できます。"],"strengths":["表示速度が非常に速い","SEOに強い","必要な箇所だけ動的にできる","運用コストが低い"],"suitableCases":["コーポレートサイト","オウンドメディア・ブログ","製品ドキュメントサイト"],"unsuitableCases":["ログインを伴う会員制システム","頻繁にデータが更新される管理画面"],"expectedFeatures":["記事・ページ管理","検索","お問い合わせフォーム","SEOメタデータ管理"]}', 8);
INSERT INTO registry_stack_presets (id, release_id, preset_type, preset_kind, parent_pattern_id, name, app_type_ids, details_json, sort_order) VALUES ('WEB-10', 1, 'tech_pattern', NULL, NULL, 'エッジAPI構成', NULL, '{"shortSummary":"Honoなどの軽量フレームワークで、エッジ環境から低遅延にAPIを提供する構成です。","primaryUse":"低遅延APIの構築","architectureType":"エッジAPI構成","primaryLanguage":"TypeScript中心","whatYouCanBuild":"Honoで実装した軽量なAPIをエッジ環境で動かし、Webhookの受信やフロントエンド向けの軽量なBFF、グローバルに配信するAPIを構築できます。","whyRecommended":["世界各地のエッジで実行されるため、地域による応答速度のばらつきを抑えたい低遅延なAPIに向いています。"],"strengths":["応答速度が速い","世界中に分散配信できる","軽量で構成がシンプル"],"suitableCases":["低遅延が求められるWebhook受信","フロントエンド向けの軽量BFF","グローバル配信するAPI"],"unsuitableCases":["大規模で複雑な業務ロジックを持つAPI","長時間かかるバッチ処理"],"expectedFeatures":["Webhook受信","API中継・変換","軽量な認証チェック"]}', 9);
INSERT INTO registry_stack_presets (id, release_id, preset_type, preset_kind, parent_pattern_id, name, app_type_ids, details_json, sort_order) VALUES ('WEB-11', 1, 'tech_pattern', NULL, NULL, 'ドキュメントDB Webアプリ', NULL, '{"shortSummary":"MongoDBなどのドキュメントDBを使い、変化しやすいデータ構造のWebアプリを構築する構成です。","primaryUse":"コンテンツ・カタログ管理","architectureType":"ドキュメントDB構成","primaryLanguage":"TypeScript中心","whatYouCanBuild":"MongoDBのようなドキュメントDBを使い、コンテンツ管理システムや、商品属性が頻繁に変わるカタログサービスなど、データ構造が変化しやすいWebアプリを構築できます。","whyRecommended":["スキーマを固定しないドキュメントDBにより、項目追加や構造変更の多いサービスでも、DBのマイグレーションに悩まされにくくなります。"],"strengths":["データ構造の変更に強い","柔軟な属性管理ができる","JSONに近い形式で扱いやすい"],"suitableCases":["コンテンツ管理システム","属性が頻繁に変わる商品カタログ","ログ・イベント中心のサービス"],"unsuitableCases":["複雑なリレーションを持つ会計・在庫データ","厳密なトランザクション整合性が必須なシステム"],"expectedFeatures":["コンテンツの登録・一覧・編集","属性・タグ管理","検索・絞り込み"]}', 10);
INSERT INTO registry_stack_presets (id, release_id, preset_type, preset_kind, parent_pattern_id, name, app_type_ids, details_json, sort_order) VALUES ('MOB-01', 1, 'tech_pattern', NULL, NULL, 'Flutter＋Firebase標準', NULL, '{"shortSummary":"FlutterとFirebaseで、iOS・Android・Webを一つのコードで開発する標準的なモバイルアプリ構成です。","primaryUse":"モバイルアプリ開発","architectureType":"クロスプラットフォーム構成","primaryLanguage":"Dart中心","whatYouCanBuild":"Flutterで作った単一のコードベースから、iOS・Androidアプリを同時にリリースし、Firebase Authenticationでのログイン、Firestoreでのデータ管理、Cloud Storageでのファイル保存を備えたモバイルアプリを構築できます。","whyRecommended":["画面とバックエンド機能を一気通貫でGoogle製品に統一できるため、モバイルアプリを短期間で複数OS向けに展開したい場合に適しています。"],"strengths":["iOS・Androidを同時に開発できる","Firebaseで認証・DBを一括管理","ストア配布までの導線が揃っている","AIコーディングとも相性がよい"],"suitableCases":["会員制モバイルアプリを作りたい","予約・注文アプリを作りたい","社内向け業務アプリをモバイル展開したい"],"unsuitableCases":["OS標準機能を極限まで使うアプリ","複雑なリレーショナルデータを扱うアプリ"],"expectedFeatures":["ログイン・ユーザー管理","プッシュ通知","データの登録・一覧","ファイルアップロード"]}', 11);
INSERT INTO registry_stack_presets (id, release_id, preset_type, preset_kind, parent_pattern_id, name, app_type_ids, details_json, sort_order) VALUES ('MOB-02', 1, 'tech_pattern', NULL, NULL, 'Flutter＋Supabase', NULL, '{"shortSummary":"FlutterとSupabaseを組み合わせた、認証・DB込みのモバイルアプリ構成です。","primaryUse":"モバイルアプリ開発","architectureType":"クロスプラットフォーム構成","primaryLanguage":"Dart中心","whatYouCanBuild":"FlutterのアプリからSupabaseのAPI・認証・DBを直接利用し、コミュニティアプリや在庫・案件管理アプリなど、サーバー開発を最小限にしたモバイルアプリを構築できます。","whyRecommended":["SQLベースのPostgreSQLを使いたいがFirebaseのようなマネージド体験も欲しい、という場合にバランスの良い選択肢です。"],"strengths":["SQLベースで構造化されたデータを扱える","リアルタイム更新に対応","Web版と同じバックエンドを共有できる"],"suitableCases":["コミュニティアプリを作りたい","在庫・案件管理アプリをモバイル化したい"],"unsuitableCases":["Google製品への統一を重視する場合","オフライン同期を多用するアプリ"],"expectedFeatures":["ログイン・ユーザー管理","データの登録・一覧・編集","ファイルアップロード","リアルタイム更新"]}', 12);
INSERT INTO registry_stack_presets (id, release_id, preset_type, preset_kind, parent_pattern_id, name, app_type_ids, details_json, sort_order) VALUES ('MOB-03', 1, 'tech_pattern', NULL, NULL, 'Flutter Web・モバイル共通', NULL, '{"shortSummary":"FlutterでWebとモバイルの両方を単一コードで展開する構成です。","primaryUse":"Web・モバイル同時展開","architectureType":"クロスプラットフォーム構成","primaryLanguage":"Dart中心","whatYouCanBuild":"Flutterで作成した画面をWebアプリとモバイルアプリの両方に展開し、展示会用アプリや、Webとアプリで同じ体験を提供したいサービスを構築できます。","whyRecommended":["画面を一つのコードベースで管理できるため、Web版とアプリ版を別々に開発・保守するコストを抑えられます。"],"strengths":["Web・モバイルを同じコードで開発","保守対象が一つで済む","デザインの統一がしやすい"],"suitableCases":["Web・アプリ両対応のサービスを作りたい","展示会・イベント用アプリを作りたい"],"unsuitableCases":["Web版のSEOを重視する場合","OS固有の高度な機能が必要な場合"],"expectedFeatures":["ログイン","コンテンツ表示","データの登録・一覧"]}', 13);
INSERT INTO registry_stack_presets (id, release_id, preset_type, preset_kind, parent_pattern_id, name, app_type_ids, details_json, sort_order) VALUES ('MOB-04', 1, 'tech_pattern', NULL, NULL, 'React Native＋Firebase', NULL, '{"shortSummary":"React NativeとFirebaseで、Web開発の知識を活かしたモバイルアプリ構成です。","primaryUse":"モバイルアプリ開発","architectureType":"クロスプラットフォーム構成","primaryLanguage":"TypeScript中心","whatYouCanBuild":"React Nativeで開発したアプリにFirebase Authenticationでのログイン、Firestoreでのデータ管理、プッシュ通知を組み合わせた会員向けモバイルアプリを構築できます。","whyRecommended":["Webで培ったReactの知識を活かしてモバイルアプリを開発できるため、Webチームがそのままモバイル展開する際に習得コストを抑えられます。"],"strengths":["Reactの知識をそのまま活かせる","Webチームと技術を統一できる","Firebaseで開発が速い"],"suitableCases":["ReactチームによるiOS・Androidアプリ開発","プッシュ通知を伴う会員アプリ"],"unsuitableCases":["ネイティブの描画性能を極限まで求める場合","FlutterやSupabaseに統一したい場合"],"expectedFeatures":["ログイン・ユーザー管理","プッシュ通知","データの登録・一覧"]}', 14);
INSERT INTO registry_stack_presets (id, release_id, preset_type, preset_kind, parent_pattern_id, name, app_type_ids, details_json, sort_order) VALUES ('MOB-05', 1, 'tech_pattern', NULL, NULL, 'React Native＋Supabase', NULL, '{"shortSummary":"React NativeとSupabaseを組み合わせた、Web版と一貫性のあるモバイルアプリ構成です。","primaryUse":"モバイルアプリ開発","architectureType":"クロスプラットフォーム構成","primaryLanguage":"TypeScript中心","whatYouCanBuild":"React NativeのアプリからSupabaseのDB・認証・ストレージを利用し、SupabaseベースのSaaSのモバイル版や業務アプリのモバイル展開を構築できます。","whyRecommended":["WebとモバイルでSupabaseという同じバックエンドを共有できるため、Web版と一貫したデータ構造・認証をモバイルアプリでも使い回せます。"],"strengths":["Web版とバックエンドを共有できる","SQLベースでデータを扱える","Reactの知識を活かせる"],"suitableCases":["SupabaseベースのSaaSのモバイル版を作りたい","業務アプリをモバイル展開したい"],"unsuitableCases":["Firebase中心の構成にしたい場合","ネイティブ性能を最優先する場合"],"expectedFeatures":["ログイン・ユーザー管理","データの登録・一覧・編集","ファイルアップロード"]}', 15);
INSERT INTO registry_stack_presets (id, release_id, preset_type, preset_kind, parent_pattern_id, name, app_type_ids, details_json, sort_order) VALUES ('MOB-06', 1, 'tech_pattern', NULL, NULL, 'ネイティブ＋Firebase', NULL, '{"shortSummary":"ネイティブアプリとFirebaseを組み合わせた、性能重視のモバイルアプリ構成です。","primaryUse":"高性能モバイルアプリ開発","architectureType":"ネイティブ構成","primaryLanguage":"Swift / Kotlin","whatYouCanBuild":"Swift・Kotlinで実装したネイティブアプリにFirebaseの認証・DB・ストレージを組み合わせ、カメラやセンサーなど端末機能を多用する高性能なモバイルアプリを構築できます。","whyRecommended":["OS標準のAPIに直接アクセスできるため、描画性能や応答速度を最優先したいアプリに最も適しています。"],"strengths":["最高水準の描画性能・応答速度","OS標準機能にフルアクセスできる","Firebaseで開発を効率化できる"],"suitableCases":["高い描画性能が求められるアプリ","カメラ・センサーを多用するアプリ"],"unsuitableCases":["開発コストを抑えたい場合","短期間で複数OSへ同時展開したい場合"],"expectedFeatures":["ログイン・ユーザー管理","カメラ・センサー連携","プッシュ通知"]}', 16);
INSERT INTO registry_stack_presets (id, release_id, preset_type, preset_kind, parent_pattern_id, name, app_type_ids, details_json, sort_order) VALUES ('MOB-07', 1, 'tech_pattern', NULL, NULL, 'Webアプリ・モバイル共通', NULL, '{"shortSummary":"既存のWebアプリをCapacitorでラップし、モバイルアプリとしても配布できる構成です。","primaryUse":"既存Webのモバイル展開","architectureType":"ハイブリッド構成","primaryLanguage":"TypeScript中心","whatYouCanBuild":"既存のWebアプリをCapacitorでラップし、追加の作り直しをせずにiOS・Androidアプリとしてストア配布できます。","whyRecommended":["すでに動いているWebサービスの資産を活かしてモバイル展開できるため、モバイル版を最小コストで実現したい場合に向いています。"],"strengths":["既存Webの資産をそのまま活用できる","開発コストを抑えられる","端末機能への部分的なアクセスも可能"],"suitableCases":["既存SaaSのモバイル版を展開したい","社内Webツールをアプリ化したい"],"unsuitableCases":["ネイティブ並みの描画性能が必要","アプリ専用の複雑な操作体験が必要"],"expectedFeatures":["既存Web機能のアプリ化","プッシュ通知","ホーム画面アイコン配置"]}', 17);
INSERT INTO registry_stack_presets (id, release_id, preset_type, preset_kind, parent_pattern_id, name, app_type_ids, details_json, sort_order) VALUES ('DESK-01', 1, 'tech_pattern', NULL, NULL, '軽量デスクトップ', NULL, '{"shortSummary":"React＋Tauriで、軽量・省メモリなWindows・Mac向けデスクトップアプリを作る構成です。","primaryUse":"軽量デスクトップツール開発","architectureType":"軽量デスクトップ構成","primaryLanguage":"TypeScript / Rust","whatYouCanBuild":"React＋Tauriで、社内ツールのデスクトップ版や、ファイル処理を伴う軽量なツールを、Windows・Mac向けに軽量なアプリとして構築できます。","whyRecommended":["Electronに比べてアプリサイズやメモリ使用量を抑えられるため、配布のしやすさや動作の軽さを重視する社内ツールに向いています。"],"strengths":["アプリサイズが小さい","メモリ使用量が少ない","Web技術で画面を開発できる"],"suitableCases":["社内ツールのデスクトップ版を作りたい","ファイル処理を伴う軽量ツールを作りたい"],"unsuitableCases":["Node.jsの豊富なライブラリを多用したい場合","複雑なマルチウィンドウ操作が必要な場合"],"expectedFeatures":["ファイル操作","ローカルデータ保存","ローカル認証"]}', 18);
